// Une ligne par recherche : chaque métier × chaque département × chaque page (25 entreprises par page)
const c = $('Critères de recherche').first().json
const metiers = String(c.metiers || '').split('\n').map(l => l.split('=')).filter(([naf]) => naf && naf.trim())
  .map(([naf, metier]) => ({ naf: naf.trim().toUpperCase(), metier: (metier || '').trim() }))
const departements = String(c.departements || '').split(/[,;\s]+/).filter(Boolean)
const recherches = []
for (const m of metiers) for (const departement of departements) for (let page = 1; page <= (c.pages || 1); page++)
  recherches.push({ json: { ...m, departement, page } })
return recherches

// Écarte : les entreprises qui refusent la prospection commerciale (droit d'opposition SIRENE),
// celles à diffusion restreinte, celles déjà dans la feuille, et les doublons.
const deja = new Set($('Lire les prospects déjà connus').all().map(i => String(i.json.siren || '')).filter(Boolean))
const metierDe = Object.fromEntries($('Pages à lire').all().map(i => [i.json.naf, i.json.metier]))
const { max_entreprises } = $('Critères de recherche').first().json
const vus = new Set()
const prospects = []
for (const { json: e } of $input.all()) {
  if (e.opposition_diffusion_commerciale || e.statut_diffusion !== 'O') continue
  if (deja.has(e.siren) || vus.has(e.siren)) continue
  const etab = (e.matching_etablissements || []).find(x => x.etat_administratif === 'A')   // établissement ouvert dans le département
  if (!etab) continue
  vus.add(e.siren)
  prospects.push({ json: {
    siren: e.siren,
    nom: etab.nom_commercial || (etab.liste_enseignes || [])[0] || e.nom_complet,
    metier: metierDe[e.activite_principale] || '',
    activite: e.activite_principale,
    adresse: etab.adresse,
    code_postal: etab.code_postal,
    ville: etab.libelle_commune,
  } })
}
return prospects.slice(0, max_entreprises || 80)

const lieu = ($json.places || [])[0] || {}
return { json: {
  ...$('Garder les prospects utilisables').item.json,
  site: lieu.websiteUri || '',
  telephone: lieu.nationalPhoneNumber || '',
  nom_google: lieu.displayName?.text || '',   // à comparer au nom : Google peut renvoyer une autre entreprise
} }

function reperer(html) {
  const h = String(html || '').toLowerCase()
  const OUTILS = [
    ['WordPress', /wp-content|wp-includes/], ['Wix', /wixstatic|wix\.com/], ['Shopify', /cdn\.shopify|myshopify/],
    ['Squarespace', /squarespace/], ['Webflow', /website-files\.com|webflow\.js/], ['Jimdo', /jimdo/],
    ['PrestaShop', /prestashop/], ['WooCommerce', /woocommerce/], ['Google Sites', /sites\.google\.com/],
    ['Calendly', /calendly\.com/], ['Doctolib', /doctolib\.fr/], ['Planity', /planity\.com/], ['Resalib', /resalib\.fr/],
    ['Treatwell', /treatwell/], ['Zenchef', /zenchef/], ['TheFork', /thefork|lafourchette/], ['Google Agenda', /calendar\.google\.com|calendar\.app\.google/],
    ['HubSpot', /hs-scripts|hubspot/], ['Brevo', /sendinblue|brevo\.com|sibforms/], ['Mailchimp', /mailchimp|list-manage\.com/],
    ['Stripe', /js\.stripe\.com/], ['PayPal', /paypal\.com/], ['SumUp', /sumup/],
    ['Crisp', /crisp\.chat/], ['Tawk.to', /tawk\.to/], ['Intercom', /intercom/], ['Zendesk', /zdassets|zendesk/], ['WhatsApp', /wa\.me\/|api\.whatsapp\.com/],
    ['Typeform', /typeform/], ['Google Forms', /docs\.google\.com\/forms|forms\.gle/], ['Jotform', /jotform/],
  ]
  const outils = OUTILS.filter(([, re]) => re.test(h)).map(([nom]) => nom)
  const a = noms => noms.filter(n => outils.includes(n))
  const rdv = a(['Calendly', 'Doctolib', 'Planity', 'Resalib', 'Treatwell', 'Zenchef', 'TheFork', 'Google Agenda'])
  const crm = a(['HubSpot', 'Brevo', 'Mailchimp'])
  const chat = a(['Crisp', 'Tawk.to', 'Intercom', 'Zendesk', 'WhatsApp'])
  const boutique = a(['Shopify', 'WooCommerce', 'PrestaShop']).length > 0 || /ajouter au panier|add to cart/.test(h)
  const formulaire = /<form[\s>]/.test(h.replace(/<form[^>]*(search|recherche)[^>]*>/g, '')) || a(['Typeform', 'Google Forms', 'Jotform']).length > 0
  const devis = /demande de devis|devis gratuit|devis en ligne|demander un devis/.test(h)
  if (formulaire) outils.push('formulaire de contact')

  const pistes = []
  if (boutique) pistes.push('mettre à jour commandes, stock et suivi client automatiquement')
  if (devis) pistes.push('préparer automatiquement les demandes de devis reçues par le site')
  if (rdv.length) pistes.push(`relier les rendez-vous pris sur ${rdv[0]} au fichier client et aux rappels`)
  if (formulaire && !crm.length && !devis) pistes.push('faire arriver les demandes du formulaire directement dans un fichier client')
  if (chat.length) pistes.push('répondre automatiquement aux questions les plus fréquentes')
  if (!formulaire && !rdv.length && !boutique) pistes.push('ajouter un formulaire ou une prise de rendez-vous en ligne reliés à vos outils')
  return { outils: outils.join(', '), pistes: pistes.slice(0, 2).join(' ; ') }
}

const r = reperer($json.html)
return { json: { ...$('Ajouter site et téléphone').item.json, html: $json.html, outils: r.outils, pistes: r.pistes } }

function chercherEmail(html, site) {
  const origine = (String(site || '').match(/^https?:\/\/[^\/?#]+/i) || [''])[0]
  const domaine = origine.replace(/^https?:\/\/(www\.)?/i, '').replace(/:\d+$/, '').toLowerCase()
  const texte = String(html || '')
    .replace(/&#64;|&#x40;|\[at\]|\(at\)| arobase /gi, '@')
    .replace(/%40/g, '@')
  const trouves = [...new Set((texte.match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi) || []).map(e => e.toLowerCase()))]
    .filter(e => !/\.(png|jpe?g|gif|svg|webp|css|js)$/.test(e))          // noms d'images du type logo@2x.png
    .filter(e => !/(sentry|wixpress|example|exemple|domain|votre|email@|nom@|user@)/.test(e))
  const generique = /^(contact|info|infos|accueil|bonjour|hello|devis|commercial|secretariat|administration|agence|atelier)@/
  const score = e => (domaine && e.endsWith('@' + domaine) ? 2 : 0) + (generique.test(e) ? 1 : 0)
  const email = trouves.sort((a, b) => score(b) - score(a))[0] || ''
  // Lien vers une page contact ou mentions légales, pour un second essai si rien n'est trouvé
  const lien = (String(html || '').match(/href=["']([^"'#]*(contact|mentions)[^"'#]*)["']/i) || [])[1] || ''
  let lien_contact = ''
  if (lien && !/^(mailto|tel|javascript):/i.test(lien)) {
    if (/^https?:\/\//i.test(lien)) lien_contact = lien
    else if (lien.startsWith('//')) lien_contact = 'https:' + lien
    else if (lien.startsWith('/')) lien_contact = origine + lien
    else lien_contact = String(site).replace(/[^\/]*$/, '') + lien
  }
  return { email, lien_contact }
}

const { html, ...base } = $json
const r = chercherEmail(html, base.site)
return { json: { ...base, email: r.email, source_email: r.email ? base.site : '', lien_contact: r.lien_contact } }

